// Consumer-side: dedupe + state change in ONE local txn.
// Relay may deliver twice; second delivery is a no-op.
void onOrderCreated(Connection conn, String eventId, String orderId) {
    conn.setAutoCommit(false);
    try {
        int inserted = insert("INSERT INTO processed_events(id) VALUES (?)", eventId);
        if (inserted == 0) { conn.rollback(); return; } // duplicate
        applyCreditOffer(conn, orderId); // business effect
        conn.commit();
    } catch (Exception e) { conn.rollback(); throw e; }
}
